sys_script.script:
switch(current.category.toString()) {

    case "water_leakage":
        current.ai_recommendation =
        "Dispatch Water Supply Department.\n" +
        "Inspect nearby pipeline.\n" +
        "Close nearest valve.\n" +
        "Expected resolution: 24 hours.";
        break;

    case "street_light":
        current.ai_recommendation =
        "Assign Electrical Department.\n" +
        "Inspect power supply.\n" +
        "Replace damaged bulb.\n" +
        "Expected resolution: 24 hours.";
        break;

    case "garbage":
        current.ai_recommendation =
        "Notify Sanitation Team.\n" +
        "Collect garbage.\n" +
        "Clean surrounding area.\n" +
        "Expected resolution: 12 hours.";
        break;

    case "drainage":
        current.ai_recommendation =
        "Assign Sanitation Department.\n" +
        "Remove blockage.\n" +
        "Clean drainage line.\n" +
        "Expected resolution: 48 hours.";
        break;

    case "road_damage":
        current.ai_recommendation =
        "Assign Road Maintenance Team.\n" +
        "Repair potholes.\n" +
        "Expected resolution: 3-5 days.";
        break;

    default:
        current.ai_recommendation =
        "Review complaint manually and assign the appropriate department.";
}
